/**
 * 管理员路由
 */
export default [
  {
    path: 'dashboard',
    name: 'AdminDashboard',
    component: () => import('@/views/admin/Dashboard.vue'),
    meta: { title: '仪表盘' },
  },
  {
    path: 'companies',
    name: 'AdminCompanyAudit',
    component: () => import('@/views/admin/CompanyAudit.vue'),
    meta: { title: '企业审核' },
  },
  {
    path: 'jobs',
    name: 'AdminJobAudit',
    component: () => import('@/views/admin/JobAudit.vue'),
    meta: { title: '岗位审核' },
  },
  {
    path: 'job-ranking',
    name: 'AdminJobRanking',
    component: () => import('@/views/admin/JobRanking.vue'),
    meta: { title: '热门岗位' },
  },
  {
    path: 'apply-trend',
    name: 'AdminApplyTrend',
    component: () => import('@/views/admin/ApplyTrend.vue'),
    meta: { title: '投递趋势' },
  },
]
